namespace HakutaiKagami.Core.Contracts;
public enum BanditAction { Encounter,Fight,Withdraw,Pay }
public sealed record BanditInput(EntityId Id,BanditAction Action,EntityId Site);
public sealed record BanditDecision(BanditInput Input,EntityId Actor,long At,long Revision,long Paid);
public sealed record SkirmishPerson(EntityId Id,int Side,int Health,int Morale,int Valor,int Leadership);
public sealed record Skirmish(EntityId Id,EntityId Site,EntityId Actor,long At,long LastAt,string Phase,SkirmishPerson[] People,SkirmishPerson[] Initial);
public sealed record BanditState(int Schema,string Policy,BanditDecision[] Decisions,Skirmish[] Encounters){public GuardOrder[] Jobs{get;init;}=[];[System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] public SecurityOrder[]? Security{get;init;}}
public static class BanditEncounter
{
 public const string Policy="local-bandit-person-contact-physical-payment-injury-v1";
 public static bool Enabled(ContractWorld w)=>w.NewGame?.BanditPolicy is Policy or LocalSecurity.Policy;
 public static EntityId[] Camps=>[new("site:castle"),new("site:kofu"),new("site:odawara")];
 static void Need(bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 public static Skirmish? Current(ContractWorld w)=>w.Bandits?.Encounters.LastOrDefault(e=>e.Actor==w.PlayerControl&&e.Phase is "選択待ち" or "交戦中");
 public static bool Blocks(ContractWorld w)=>Current(w)!=null;
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>GuardJobs.Orders(w).Any(q=>q.Input.Id==id)||w.Bandits?.Decisions.Any(e=>e.Input.Id==id)==true;
 public static long Net(ContractWorld w,EntityId wallet,long at,long rev)=>-(w.Bandits?.Decisions??[]).Where(e=>NewGameWork.Wallet(e.Actor)==wallet&&(e.At<at||e.At==at&&e.Revision<rev)).Sum(e=>e.Paid);
 public static long BanditMoney(ContractWorld w,EntityId site)=>(w.Bandits?.Decisions??[]).Where(e=>e.Input.Site==site).Sum(e=>e.Paid);
 public static bool Dangerous(ContractWorld w,EntityId site)=>Enabled(w)&&Camps.Contains(site)&&!(w.Bandits?.Encounters.Any(e=>e.Site==site&&e.Phase=="賊が敗走")??false);
 public static bool NeedsContact(ContractWorld w)=>SocialWorld.Site(w,w.PlayerControl) is {} site&&Dangerous(w,site)&&!LocalSecurity.Protected(w,site,w.ElapsedSeconds,w.CommitSequence+1)&&!(w.Bandits?.Encounters.Any(e=>e.Site==site&&e.Actor==w.PlayerControl)??false);
 public static int Injury(ContractWorld w,EntityId person)=>(w.Bandits?.Encounters??[]).SelectMany(e=>e.People.Where(p=>p.Id==person).Select(p=>20-p.Health)).DefaultIfEmpty().Max();
 static EntityId Member(EntityId site,int i)=>new("bandit:"+site.Value.Replace(':','/')+"/"+i);
 public static void Execute(ContractWorld w,BanditInput input,EntityId actor){Need(Enabled(w)&&actor==w.PlayerControl&&EntityId.IsValid(input.Id.Value)&&Enum.IsDefined(input.Action)&&SocialWorld.Site(w,actor)==input.Site,"本人が現地で判断してください");var current=Current(w);long paid=0;
 if(input.Action==BanditAction.Encounter){Need(current==null&&Dangerous(w,input.Site),"この現地に未解決の賊はいません");var people=new List<SkirmishPerson>();foreach(var id in PersonalCompanions.View(w).Where(p=>p.Active&&p.Nearby&&!p.Busy).Select(p=>p.Person).Prepend(actor).Distinct())people.Add(new(id,0,Math.Max(0,20-Injury(w,id)),100,CharacterDevelopment.EffectiveAt(w,id,DevelopmentAbility.Valor,w.ElapsedSeconds),CharacterDevelopment.EffectiveAt(w,id,DevelopmentAbility.Leadership,w.ElapsedSeconds)));for(int i=0;i<3;i++){var id=Member(input.Site,i);people.Add(new(id,1,Math.Max(0,20-Injury(w,id)),80,40,30));}current=new(input.Id,input.Site,actor,w.ElapsedSeconds,w.ElapsedSeconds,"選択待ち",people.ToArray(),people.ToArray());w.Bandits??=new(1,Policy,[],[]);w.Bandits=w.Bandits with{Encounters=[..w.Bandits.Encounters,current]};w.Paused=true;}
 else {Need(current!=null&&current.Site==input.Site,"対応中の接触がありません");if(input.Action==BanditAction.Pay){Need(current!.Phase=="選択待ち"&&TransportWork.WalletBefore(w,actor,w.ElapsedSeconds,w.CommitSequence)>=20,"通行銭20文が不足するか、すでに交戦中です");paid=20;}string phase=input.Action==BanditAction.Fight?"交戦中":input.Action==BanditAction.Pay?"通行銭を受領":"本人側が退避";Need(input.Action!=BanditAction.Fight||current!.People.Any(p=>p.Side==0&&p.Health>0),"負傷で戦えません。退避してください");Need(input.Action!=BanditAction.Fight||current!.Phase=="選択待ち","すでに交戦中です");Replace(w,current! with{Phase=phase,LastAt=w.ElapsedSeconds});}
 w.Bandits=w.Bandits! with{Decisions=[..w.Bandits.Decisions,new(input,actor,w.ElapsedSeconds,w.CommitSequence,paid)]};}
 static void Replace(ContractWorld w,Skirmish next)=>w.Bandits=w.Bandits! with{Encounters=w.Bandits.Encounters.Select(e=>e.Id==next.Id?next:e).ToArray()};
 static Skirmish Advance(Skirmish e,long until){if(e.Phase!="交戦中")return e;while(e.LastAt+5<=until){long at=e.LastAt+5;var input=e.People.Select((p,i)=>new ContactParticipant(p.Id,p.Side,new(p.Side==0?0:3000,(i%3)*500),0,p.Health,p.Morale,p.Morale<=25||p.Health==0?"routed":"standing")).ToArray();var hits=ContactCombat.Resolve(at,true,input);var people=e.People.Select(p=>{var hit=hits.SingleOrDefault(h=>h.Unit==p.Id);if(hit==null)return p;int other=e.People.Where(x=>x.Side!=p.Side&&x.Health>0&&x.Morale>25).Select(x=>x.Valor).DefaultIfEmpty(0).Max();int damage=Math.Max(1,hit.Soldiers*(50+other)/100);int morale=Math.Max(1,hit.Morale*(150-p.Leadership)/100);return p with{Health=Math.Max(0,p.Health-damage),Morale=Math.Max(0,p.Morale-morale)};}).ToArray();bool own=people.Any(p=>p.Side==0&&p.Health>0&&p.Morale>25),enemy=people.Any(p=>p.Side==1&&p.Health>0&&p.Morale>25);e=e with{People=people,LastAt=at,Phase=!own?"本人側が退避":!enemy?"賊が敗走":"交戦中"};if(e.Phase!="交戦中")break;}return e;}
 internal static void Tick(ContractWorld w){var e=Current(w);if(e?.Phase!="交戦中")return;var next=Advance(e,w.ElapsedSeconds);Replace(w,next);if(next.Phase!="交戦中")w.Paused=true;}
 internal static long? NextBoundary(ContractWorld w,long target)=>Current(w) is {Phase:"交戦中"} e&&e.LastAt+5<=target?e.LastAt+5:null;
 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.Bandits==null){Need(prior?.Bandits==null,"賊の原本を消せません");return;}Need(Enabled(w)&&w.Bandits.Schema==1&&w.Bandits.Policy==Policy,"賊の保存形式が不正です");Need(w.Bandits.Decisions.Select(d=>d.Input.Id).Distinct().Count()==w.Bandits.Decisions.Length,"二重の賊対応です");if(prior?.Bandits!=null)Need(w.Bandits.Decisions.Take(prior.Bandits.Decisions.Length).SequenceEqual(prior.Bandits.Decisions),"過去の通行銭・選択を変更できません");var expected=new List<Skirmish>();long revision=0,at=0;
 foreach(var d in w.Bandits.Decisions){Need(EntityId.IsValid(d.Input.Id.Value)&&Enum.IsDefined(d.Input.Action)&&d.Actor==w.PlayerControl&&d.At>=at&&d.At<=w.ElapsedSeconds&&d.Revision>revision&&d.Revision<=w.CommitSequence&&d.Paid==(d.Input.Action==BanditAction.Pay?20:0)&&TransportWork.At(w,d.Actor,d.Input.Site,d.At,d.Revision,true),"通行銭か当時の所在が不正です");if(expected.Count>0)expected[^1]=Advance(expected[^1],d.At);if(d.Input.Action==BanditAction.Encounter){Need(!expected.Any(e=>e.Site==d.Input.Site&&e.Phase=="賊が敗走")&&expected.All(e=>e.Phase is not("選択待ち" or "交戦中")),"同時に複数の接触です");var saved=w.Bandits.Encounters.Single(e=>e.Id==d.Input.Id);Need(saved.Actor==d.Actor&&saved.Site==d.Input.Site&&saved.At==d.At&&Camps.Contains(saved.Site),"接触の発生原本が違います");Need(saved.Initial.Select(p=>p.Id).Distinct().Count()==saved.Initial.Length&&saved.Initial.Count(p=>p.Side==1)==3&&saved.Initial.Any(p=>p.Id==d.Actor&&p.Side==0),"人数が不正です");foreach(var person in saved.Initial){int injury=expected.SelectMany(e=>e.People.Where(p=>p.Id==person.Id).Select(p=>20-p.Health)).DefaultIfEmpty().Max();Need(person.Health==Math.Max(0,20-injury),"負傷の持越しが不正です");if(person.Side==1)Need(Enumerable.Range(0,3).Any(i=>Member(saved.Site,i)==person.Id)&&person.Valor==40&&person.Leadership==30&&person.Morale==80,"賊の個体が不正です");else{Need(person.Side==0&&TransportWork.At(w,person.Id,saved.Site,d.At,d.Revision,true)&&person.Valor==CharacterDevelopment.EffectiveAt(w,person.Id,DevelopmentAbility.Valor,d.At)&&person.Leadership==CharacterDevelopment.EffectiveAt(w,person.Id,DevelopmentAbility.Leadership,d.At)&&person.Morale==100,"参加者の能力か所在が不正です");if(person.Id!=d.Actor)Need(w.Companions?.Orders.Where(q=>q.Input.Person==person.Id&&q.At<=d.At&&q.Revision<d.Revision&&q.Input.Action is CompanionAction.Agree or CompanionAction.EndAgreement).LastOrDefault()?.Input.Action==CompanionAction.Agree,"同行の合意がありません");}}expected.Add(saved with{People=saved.Initial,LastAt=d.At,Phase="選択待ち"});}
 else {Need(expected.Count>0&&expected[^1].Phase is "選択待ち" or "交戦中","終了後の再操作です");var e=expected[^1];Need(e.Site==d.Input.Site,"対応中の場所が異なります");if(d.Input.Action==BanditAction.Pay)Need(e.Phase=="選択待ち"&&TransportWork.WalletBefore(w,d.Actor,d.At,d.Revision)>=20,"当時の通行銭が不足しています");if(d.Input.Action==BanditAction.Fight)Need(e.Phase=="選択待ち"&&e.People.Any(p=>p.Side==0&&p.Health>0),"交戦開始が不正です");expected[^1]=e with{LastAt=d.At,Phase=d.Input.Action==BanditAction.Fight?"交戦中":d.Input.Action==BanditAction.Pay?"通行銭を受領":"本人側が退避"};}revision=d.Revision;at=d.At;}
 if(expected.Count>0)expected[^1]=Advance(expected[^1],w.ElapsedSeconds);Need(ContractJson.CanonicalHash(expected.ToArray())==ContractJson.CanonicalHash(w.Bandits.Encounters),"同時接触計算・負傷・敗走の再計算が一致しません");}

}
public sealed partial class WorldSession
{
 public CommandResult ManageBandits(BanditInput input,long revision){lock(gate){var old=state.Bandits?.Decisions.SingleOrDefault(e=>e.Input.Id==input.Id);if(old!=null)return new(old.Input==input?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,input.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,input.Id)||state.Requests.Any(r=>r.Id==input.Id))return new(ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>BanditEncounter.Execute(w,input,w.PlayerControl));return new(ResultCode.Accepted,input.Id,state.CommitSequence,"現地の選択を記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException){return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,e.Message);}}}
}
